------------ import ------------
local UIModule = CS.Engine.UI.UIModule
local ActionUtils = import('Game.UI.FightReady.UIMainChapter.ActionUtils')
local CountDownTime = 2592000 --30 * 86400 30天的秒数
local CDTimerModule = CS.Engine.Modules.CDTimerModule
local BehaviourAction = CS.Engine.Lib.BehaviourAction
local KTool = CS.Engine.Lib.KTool
local RegionQuestMgr = import('Game.UI.FightReady.UIMainChapter.RegionQuestMgr')
local cs_coroutine = require 'XLua.cs_coroutine'
local AnnihilationUtils = import('Game.UI.FightReady.UIMainChapter.AnnihilationUtils')
------------ import ------------

---@class ActionTeamInviteNode
---@field Env                           	ActionTeamInviteNode
---@field controller                    	Engine.Modules.LuaBehaviour | Engine.UI.UILuaDialog
---@field PromptUpItem                  	UnityEngine.RectTransform               
---@field Root                          	UnityEngine.RectTransform               
---@field MaskState                     	UnityEngine.RectTransform               
---@field TxtState                      	UnityEngine.RectTransform                                       
local ActionTeamInviteNode = Class("ActionTeamInviteNode")
function ActionTeamInviteNode:__init()
    self._data  = nil
    self._state = Constants.ActionTeamInviteNodeUIState.Show
end

function ActionTeamInviteNode:__delete()
    self._data = nil
end

function ActionTeamInviteNode:Awake()
    SetButtonAction(self.FontStyleButton, Bind(self, self.OnEntry))
    SetButtonAction(self.BtnAction, Bind(self, self.OnBtnAction))
end

function ActionTeamInviteNode:OnBtnAction()
    UIModule.OpenDialog({ id = Constants.UITypeIds.ActionTeamInvitationReceive, parameters = {data = self._data, time = self._time} }, {
    })
    KTool.SafeDelete(self.controller.gameObject)
end

function ActionTeamInviteNode:Start()

end

function ActionTeamInviteNode:OnEntry()
    if not ActionUtils.CanJump() then return end
    local activityUuid = isNull(self._data.activity) and 0 or checkNumber(self._data.activity.id)
    RegionQuestMgr:GetInstance():FriendRelpyReq({reply = 1, mainPlayerId = self._data.mainData.playerInfo.playerId, activityUuid = activityUuid})
    KTool.SafeDelete(self.controller.gameObject)
end

function ActionTeamInviteNode:Refresh(jsonData)
    self._data = jsonData
    if not self._data then
        return
    end
    self._time = 30
    self._maxTime = self._time

    self:FillSelf()
    self:StartTimeDown()

    self:ChangeState(Constants.ActionTeamInviteNodeUIState.Show)

end

function ActionTeamInviteNode:StartTimeDown()
    if not isNull(self._timeDown) then
        CDTimerModule.GetInstance():RemoveCD(self._timeDown)
        self._timeDown = nil
    end
    self._timeDown = CDTimerModule.GetInstance():AddCD(1, function(count, id)
        if self._time > 0 then
            self._time = self._time - 1
            CfUtils.FillText(self.TxtTime, self._time)
            self.Fill.fillAmount = (self._maxTime - self._time) / self._maxTime

            CfUtils.FillText(self.TxtTime2, self._time)
            self.Fill2.fillAmount = (self._maxTime - self._time) / self._maxTime
        end

        if self._time == 0 then
            KTool.SafeDelete(self.controller.gameObject)
        end
    end, CountDownTime, false, true)
end

function ActionTeamInviteNode:FillSelf()
    CfUtils.FillText(self.TxtTime, self._time)
    self.Fill.fillAmount = (self._maxTime - self._time) / self._maxTime

    CfUtils.FillText(self.TxtTime2, self._time)
    self.Fill2.fillAmount = (self._maxTime - self._time) / self._maxTime

    
    local info = self._data.mainData.playerInfo
    CfUtils.FillText(self.TxtName, info.name)

    local scr = CfUtils.GetLuaScr(self.CommonPlayerHeadNode, "Game.Behaviours.CommonPlayerHeadNode")
    if scr then
        scr:FreshAvatarFrame(info.avatar, info.avatarFrame)
    end
    
    local activityPrefabId = isNull(self._data.activity) and 0 or checkNumber(self._data.activity.prefab)
    local comp = AnnihilationUtils.GetComponent(activityPrefabId)
    local typeId = self._data.mainData.regionalBossData.bossTypeId
    local vo = comp:GetTypeVo(typeId)
    if vo then
        CfUtils.FillImage(self.ImgMonster, vo.bossPortrait2)
    end

    self._co = cs_coroutine.start(function()
        coroutine.yield(CS.UnityEngine.WaitForSeconds(2))
        local animation = KTool.GetComponent(self.Root.gameObject, typeof(CS.UnityEngine.Animation))
        animation:Play("ActionTeamInviteNodeBack")
        self:ChangeState(Constants.ActionTeamInviteNodeUIState.Downsize)
    end)
end 

function ActionTeamInviteNode:ChangeState(state)
    self._state = state
    Events.Broadcast(Constants.EventNames.ActionTeamInviteNodeChangeState, state)
    
end

---@return Constants.ActionTeamInviteNodeUIState
function ActionTeamInviteNode:GetState()
    return self._state
end

function ActionTeamInviteNode:OnDestroy()
    if not isNull(self._timeDown) then
        CDTimerModule.GetInstance():RemoveCD(self._timeDown)
        self._timeDown = nil
    end
    if self._co then
        cs_coroutine.stop(self._co)
        self._co = nil
    end
    self:ChangeState(Constants.ActionTeamInviteNodeUIState.Close)
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
    self = nil
end

return ActionTeamInviteNode